class Solution {
public:
    long long minCost(std::vector<int>& basket1, std::vector<int>& basket2) {
        std::unordered_map<int, int> count;
        int min_val = INT_MAX;
        for (int x : basket1) {
            count[x]++;
            min_val = std::min(min_val, x);
        }
        for (int x : basket2) {
            count[x]--;
            min_val = std::min(min_val, x);
        }
        std::vector<int> swaps;
        for (auto& [val, diff] : count) {
            if (diff % 2 != 0) return -1;
            for (int i = 0; i < std::abs(diff) / 2; ++i) {
                swaps.push_back(val);
            }
        }
        std::sort(swaps.begin(), swaps.end());
        long long ans = 0;
        int m = swaps.size() / 2;
        for (int i = 0; i < m; ++i) {
            ans += std::min((long long)swaps[i], 2LL * min_val);
        }
        return ans;
    }
};

class Solution {
    public long minCost(int[] basket1, int[] basket2) {
        java.util.Map<Integer, Integer> count = new java.util.HashMap<>();
        int minVal = Integer.MAX_VALUE;
        for (int x : basket1) {
            count.put(x, count.getOrDefault(x, 0) + 1);
            minVal = Math.min(minVal, x);
        }
        for (int x : basket2) {
            count.put(x, count.getOrDefault(x, 0) - 1);
            minVal = Math.min(minVal, x);
        }
        java.util.List<Integer> swaps = new java.util.ArrayList<>();
        for (java.util.Map.Entry<Integer, Integer> entry : count.entrySet()) {
            int diff = entry.getValue();
            if (diff % 2 != 0) return -1;
            for (int i = 0; i < Math.abs(diff) / 2; i++) {
                swaps.add(entry.getKey());
            }
        }
        java.util.Collections.sort(swaps);
        long ans = 0;
        int m = swaps.size() / 2;
        for (int i = 0; i < m; i++) {
            ans += Math.min((long) swaps.get(i), 2L * minVal);
        }
        return ans;
    }
}

var minCost = function(basket1, basket2) {
    const count = new Map();
    let minVal = Infinity;
    for (const x of basket1) {
        count.set(x, (count.get(x) || 0) + 1);
        minVal = Math.min(minVal, x);
    }
    for (const x of basket2) {
        count.set(x, (count.get(x) || 0) - 1);
        minVal = Math.min(minVal, x);
    }
    const swaps = [];
    for (const [val, diff] of count.entries()) {
        if (diff % 2 !== 0) return -1;
        for (let i = 0; i < Math.abs(diff) / 2; i++) {
            swaps.push(val);
        }
    }
    swaps.sort((a, b) => a - b);
    let ans = 0;
    const m = swaps.length / 2;
    for (let i = 0; i < m; i++) {
        ans += Math.min(swaps[i], 2 * minVal);
    }
    return ans;
};
